import sys

n, goal, k = map(int, sys.stdin.read().split())
M = 10**9 + 7
total = 0
stack = [[]]
while stack:
    seq = stack.pop()
    if len(seq) == goal:
        if len(set(seq)) == n:
            total += 1
        continue
    recent = seq[max(0, len(seq) - k):] if k > 0 else []
    for s in range(n):
        if s not in recent:
            stack.append(seq + [s])
print(total % M)

